    <style>
        :root {
            --primary-color: #002D7A;
            --accent-color: #f8f9fa;
            --text-color: #333;
            --bg-color: #F7FAFC;
            --white: #ffffff;
            --shadow: 0 4px 6px rgba(0,0,0,0.1);
            --transition: all 0.3s ease;
        }

        body {
            font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-color);
            margin: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            overflow-x: hidden;
        }

        .app-container {
            width: 100%;
            max-width: 600px;
            margin: 20px;
            background: var(--white);
            padding: 30px;
            border-radius: 20px;
            box-shadow: var(--shadow);
            text-align: center;
            position: relative;
        }

        .screen {
            display: none;
            animation: fadeIn 0.5s ease forwards;
        }

        .screen.active {
            display: block;
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        h1 {
            color: var(--primary-color);
            font-size: 24px;
            margin-bottom: 20px;
        }

        p {
            font-size: 16px;
            line-height: 1.5;
            margin-bottom: 25px;
            color: #666;
        }

        .btn {
            background-color: var(--primary-color);
            color: var(--white);
            border: none;
            padding: 15px 30px;
            font-size: 18px;
            font-weight: bold;
            border-radius: 10px;
            cursor: pointer;
            transition: var(--transition);
            text-decoration: none;
            display: inline-block;
        }

        .btn:hover {
            filter: brightness(1.2);
            transform: scale(1.05);
        }

        .progress-bar {
            width: 100%;
            height: 8px;
            background-color: #eee;
            border-radius: 4px;
            margin-bottom: 30px;
            overflow: hidden;
        }

        .progress-fill {
            height: 100%;
            background-color: var(--primary-color);
            width: 0%;
            transition: width 0.3s ease;
        }

        .ranking-container {
            margin: 30px 0;
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .rank-item {
            background: var(--accent-color);
            padding: 15px;
            border: 2px solid transparent;
            border-radius: 12px;
            cursor: grab;
            display: flex;
            align-items: center;
            gap: 15px;
            transition: var(--transition);
            user-select: none;
            font-weight: 500;
            font-size: 17px;
        }

        .rank-item:active {
            cursor: grabbing;
        }

        .rank-item.dragging {
            opacity: 0.5;
            background: #e2e8f0;
            border-color: var(--primary-color);
        }

        .rank-label {
            font-size: 12px;
            text-transform: uppercase;
            color: #999;
            margin-bottom: 5px;
        }

        .rank-item::before {
            content: '≡';
            color: #ccc;
            font-size: 20px;
        }

        .rank-guide {
