    const INTERPRETATIONS = {
        d: {
            title: "Ваш ведущий тип — Доминирование (D)",
            text: "Вы решительны, прямолинейны и ориентированы на результат. Вам нравится брать на себя ответственность, ставить амбициозные цели и преодолевать препятствия. Вы цените эффективность и скорость принятия решений."
