        c: {
            title: "Ваш ведущий тип — Соответствие (C)",
            text: "Вы аналитичны, точны и внимательны к деталям. Вы цените логику, стандарты и качество. Ваша сильная сторона — умение глубоко разбираться в вопросе, планировать и обеспечивать высокую точность исполнения."
        }
    };

    class DiscApp {
        constructor() {
            this.currentIndex = 0;
            this.scores = { d: 0, i: 0, s: 0, c: 0 };
            this.currentOrder = [];
        }

        showScreen(//id) {
            document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
            document.getElementById(`screen-${id}`).classList.add('active');
        }

        start() {
            this.showScreen('test');
            this.renderQuestion();
        }

        renderQuestion() {
            const container = document.getElementById('ranking-container');
            const progress = document.getElementById('progress-fill');

            const questions = QUESTIONS[this.currentIndex];

            // Shuffle adjectives slightly for variety
            const shuffled = [...questions].sort(() => Math.random() - 0.5);
            this.currentOrder = shuffled;

            container.innerHTML = '';
            shuffled.forEach((item, index) => {
                const div = document.createElement('div');
                div.className = 'rank-item';
                div.draggable = true;
                div.dataset.index = index;
                div.dataset.type = item.type;
                div.textContent = item.text;

                div.addEventListener('dragstart', (e) => {
                    div.classList.add('dragging');
                    e.dataTransfer.setData('text/plain', index);
                });

                div.addEventListener('dragend', () => {
                    div.classList.remove('dragging');
                });

                container.appendChild(div);
            });

            // Setup drag and drop
            container.addEventListener('dragover', (e) => {
                e.preventDefault();
                const afterElement = this.getDragAfterElement(container, e.clientY);
                const draggable = document.querySelector('.dragging');
                if (afterElement == null) {
                    container.appendChild(draggable);
                } else {
                    container.insertBefore(draggable, afterElement);
                }
            });

            progress.style.width = `${((this.currentIndex) / QUESTIONS.length) * 100}%`;
        }

        getDragAfterElement(container, y) {
            const draggableElements = [...container.querySelectorAll('.rank-item:not(.dragging)')];

            return draggableElements.reduce((closest, child) => {
                const box = {};
                const offset = child.offsetTop;
                const distance = y - offset - child.getBoundingClientRect().height / 2;

                if (distance < 0 && distance > closest.offset) {
                    return { offset: distance, element: child };
                } else {
                    return closest;
                }
            }, { offset: Number.NEGATIVE_INFINITY }).element;
        }

        next() {
            // Calculate points for this question based on final DOM order
            const items = [...document.querySelectorAll('.rank-item')];
            items.forEach((item, index) => {
                const type = item.dataset.type;
                // Rank 1 = 4pt, Rank 2 = 3pt, Rank 3 = 2pt, Rank 4 = 1pt
                this.scores[type] += (4 - index);
            });

            this.currentIndex++;
            if (this.currentIndex < QUESTIONS.length) {
                this.renderQuestion();
            } else {
                this.finish();
            }
        }

        async finish() {
            this.showScreen('loading');

            // Simulate processing
            await new Promise(resolve => setTimeout(resolve, 2000));

            this.showResults();
        }

        showResults() {
            this.showScreen('results');

            document.getElementById('score-d').textContent = this.scores.d;
            document.getElementById('score-i').textContent = this.scores.i;
            document.getElementById('score-s').textContent = this.scores.s;
            document.getElementById('score-c').textContent = this.scores.c;

            // Find dominant type
            let dominant = 'd';
            let maxScore = this.scores.d;

            if (this.scores.i > maxScore) { maxScore = this.scores.i; dominant = 'i'; }
            if (this.scores.s > maxScore) { maxScore = this.scores.s; dominant = 's'; }
            if (this.scores.c > maxScore) { maxScore = this.scores.c; dominant = 'c'; }

            const interpretation = INTERPRETATIONS[dominant];
            document.getElementById('main-result-text').innerHTML = `
                <h3>${interpretation.title}</h3>
                <p>${interpretation.text}</p>
            `;
        }
    }

    const app = new DiscApp();
</script>
